            if (getMiscWeather200ResponseHourlyForecastInner.PopOption.IsSet)
                writer.WriteNumber("pop", getMiscWeather200ResponseHourlyForecastInner.PopOption.Value!.Value);

            if (getMiscWeather200ResponseHourlyForecastInner.UvIndexOption.IsSet)
                writer.WriteNumber("uv_index", getMiscWeather200ResponseHourlyForecastInner.UvIndexOption.Value!.Value);
        }
    }
}
